import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.cities().listCities(Map.of("country", "AU", "state", "VIC", "limit", 20));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("cities")) {
    Map<?, ?> city = (Map<?, ?>) row;
    Map<?, ?> state = (Map<?, ?>) city.get("state");
    System.out.println(city.get("id") + " " + city.get("name") + " " + city.get("post_code") + " " + state.get("code"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("total"));
